CREATE TABLE IF NOT EXISTS "RefreshToken" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Token" VARCHAR(255) NOT NULL,
    "UserId" VARCHAR(50) NOT NULL,
    "ExpiryDate" TIMESTAMP NOT NULL,
    "Revoked" BOOLEAN DEFAULT FALSE,
    CONSTRAINT "FK_RefreshToken_User" FOREIGN KEY ("UserId") REFERENCES "User" ("UserId")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_RefreshToken_Token" ON "RefreshToken" ("Token");

CREATE TABLE IF NOT EXISTS "PasswordResetToken" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Token" VARCHAR(255) NOT NULL,
    "UserId" VARCHAR(50) NOT NULL,
    "ExpiryDate" TIMESTAMP NOT NULL,
    "Used" BOOLEAN DEFAULT FALSE,
    "CreatedAt" TIMESTAMP,
    CONSTRAINT "FK_PasswordResetToken_User" FOREIGN KEY ("UserId") REFERENCES "User" ("UserId")
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_PasswordResetToken_Token" ON "PasswordResetToken" ("Token");